// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! The root system's GUMBO functions, for the system assertions.

use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

